"use strict";(self.webpackChunk=self.webpackChunk||[]).push([[2980],{7483:(a,e,n)=>{n.r(e),n.d(e,{data:()=>i});const i={key:"v-1c7bb168",path:"/pl_PL/troubleshooting.html",title:"Rozwiązywanie problemów",lang:"pl-PL",frontmatter:{},excerpt:"",headers:[{level:2,title:"Unlaunch",slug:"unlaunch",children:[{level:3,title:"Czy Unlaunch zamraża się na MISMATCH IN FAT COPIES?",slug:"czy-unlaunch-zamraza-sie-na-mismatch-in-fat-copies",children:[]},{level:3,title:'Nie ma dźwięku lub boot splashu podczas uruchamiania "LAUNCHER" za pomocą Unlaunch',slug:"nie-ma-dzwieku-lub-boot-splashu-podczas-uruchamiania-launcher-za-pomoca-unlaunch",children:[]}]}],filePathRelative:"pl_PL/troubleshooting.md",git:{updatedTime:1635476023e3,contributors:[{name:"Pk11",email:"epicpkmn11@outlook.com",commits:1}]}}},5361:(a,e,n)=>{n.r(e),n.d(e,{default:()=>u});const i=(0,n(6252).uE)('<h1 id="rozwiazywanie-problemow" tabindex="-1"><a class="header-anchor" href="#rozwiazywanie-problemow" aria-hidden="true">#</a> Rozwiązywanie problemów</h1><h2 id="unlaunch" tabindex="-1"><a class="header-anchor" href="#unlaunch" aria-hidden="true">#</a> Unlaunch</h2><h3 id="czy-unlaunch-zamraza-sie-na-mismatch-in-fat-copies" tabindex="-1"><a class="header-anchor" href="#czy-unlaunch-zamraza-sie-na-mismatch-in-fat-copies" aria-hidden="true">#</a> Czy Unlaunch zamraża się na <code>MISMATCH IN FAT COPIES</code>?</h3><p>twlnf ma krytyczny błąd, w którym nie aktualizuje poprawnie całego NAND po jego modyfikacji, który powoduje, że niektóre homebrew (takie jak Unlaunch installer) wyrzucą błąd.</p><p>O ile jest to naprawialne, metoda w dużej mierze różni się w zależności od systemów. Jedną z metod jest usunięcie dowolnego DSiWare zainstalowanego przez twlnf, ale zgłoszono również, że przeniesienie <em>wszystkich</em> DSiWare na kartę SD i powrót do systemu może również okazać się pomocne.</p><p>Jeśli w przeszłości zdowngradowałeś system, aktualizacja do wersji v1.4.5 (lub v1.4.6 jeśli Twój region DS jest chiński lub koreański) może również pomóc w tym błędzie.</p><h3 id="nie-ma-dzwieku-lub-boot-splashu-podczas-uruchamiania-launcher-za-pomoca-unlaunch" tabindex="-1"><a class="header-anchor" href="#nie-ma-dzwieku-lub-boot-splashu-podczas-uruchamiania-launcher-za-pomoca-unlaunch" aria-hidden="true">#</a> Nie ma dźwięku lub boot splashu podczas uruchamiania &quot;LAUNCHER&quot; za pomocą Unlaunch</h3><p>Twórca Unlaunch (nocash) celowo załatał domyślnie dźwięk w tle i boot-splash. Możesz odzyskać te efekty <a href="/installing-unlaunch">ponownie instalując Unlaunch</a> używając TWiLight Menu++.</p>',8),o={},u=(0,n(3744).Z)(o,[["render",function(a,e){return i}]])},3744:(a,e)=>{e.Z=(a,e)=>{for(const[n,i]of e)a[n]=i;return a}}}]);